import sys
import traceback


def _test(expected, actual, call):
    try:
        assert actual == expected, "{} should return {}. Your code: {}".format(call, expected, actual)
        print("\u2713 passed: {} \u2192 {}".format(call, expected))
    except AssertionError as ae:
        print("\u2717 failed: {}".format(ae))


class DequeTests:

    def __init__(self, module_name):
        self.module = module_name

    def test_01_constructor(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            deque = self.module.Deque()
            print("\u2713 passed: {} constructor call".format('Deque()'))
        except Exception as e:
            print("\u2717 FAILED. The constructor raised an exception. {}: {}".format(type(e).__name__, e))
            print(traceback.format_exc())

    def test_02_adds_and_removes(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            deque = self.module.Deque()

            _test(expected=None,
                  actual=deque.add_rear('Horatio'),
                  call="add_rear('Horatio')")

            _test(expected=None,
                  actual=deque.add_rear('Inez'),
                  call="add_rear('Inez')")

            _test(expected=None,
                  actual=deque.add_rear('Jessica'),
                  call="add_rear('Jessica')")

            _test(expected='Jessica',
                  actual=deque.remove_rear(),
                  call="remove_rear()")

            _test(expected=None,
                  actual=deque.add_front('ReallyImportantPerson'),
                  call="deque.add_front('ReallyImportantPerson')")

            _test(expected='ReallyImportantPerson',
                  actual=deque.remove_front(),
                  call="deque.remove_front()")

            _test(expected='Horatio',
                  actual=deque.remove_front(),
                  call="deque.remove_front()")

            _test(expected='Inez',
                  actual=deque.remove_front(),
                  call="deque.remove_front()")

        except NotImplementedError:
            print("\u2717 FAILED: A method is raising Not Implemented")
            return
        except Exception as e:
            print(
                "\u2717 FAILED. calling add_front(), add_rear(), remove_front(), or remove_rear() raised an exception. {}: {}".format(
                    type(e).__name__, e))
            print(traceback.format_exc())

    def test_03_remove_empty(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            deque = self.module.Deque()
            _test(expected=None,
                  actual=deque.remove_rear(),
                  call="calling deque.remove_rear() on an empty deque")

            _test(expected=None,
                  actual=deque.remove_front(),
                  call="calling deque.remove_front() on an empty deque")

        except NotImplementedError:
            print("\u2717 FAILED: A method is raising Not Implemented")
            return
        except Exception as e:
            print("\u2717 FAILED. calling remove_front() or remove_rear() raised an exception. {}: {}".format(
                type(e).__name__, e))
            print(traceback.format_exc())

    def test_04_is_empty(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            deque = self.module.Deque()
            _test(expected=True,
                  actual=deque.is_empty(),
                  call="is_empty() on an empty deque")

            deque.add_rear('Jessica')
            _test(expected=False,
                  actual=deque.is_empty(),
                  call="called add_rear('Jessica'), then is_empty()")

            deque.remove_rear()
            _test(expected=True,
                  actual=deque.is_empty(),
                  call="called remove_rear(). is_empty()")

        except NotImplementedError:
            print("\u2717 FAILED: A method is raising Not Implemented")
            return
        except Exception as e:
            print("\u2717 FAILED. calling is_empty() raised an exception. {}: {}".format(type(e).__name__, e))
            print(traceback.format_exc())

    def test_05__len__(self):
        print('-' * 5, sys._getframe().f_code.co_name, '-' * 5)
        try:
            deque = self.module.Deque()
            _test(expected=0,
                  actual=len(deque),
                  call="len(deque) on an empty deque")

            deque.add_rear('Horatio')
            deque.add_rear('Inez')
            _test(expected=2,
                  actual=len(deque),
                  call="called add_rear('Horatio') then add_rear('Inex'). now len(deque)")

            deque.remove_front()
            _test(expected=1,
                  actual=len(deque),
                  call="called remove_front(). now len(deque)")

        except NotImplementedError:
            print("\u2717 FAILED: A method is raising Not Implemented")
            return
        except Exception as e:
            print("\u2717 FAILED. calling len(deque) raised an exception. {}: {}".format(type(e).__name__, e))
            print(traceback.format_exc())

    def test_all(self):
        self.test_01_constructor()
        self.test_02_adds_and_removes()
        self.test_03_remove_empty()
        self.test_04_is_empty()
        self.test_05__len__()
